from qgis.utils import plugins, active_plugins
plug = plugins.get('geo_excel')
info = {'loaded': 'geo_excel' in plugins, 'in_active': 'geo_excel' in active_plugins}
if plug is not None:
    info['type'] = type(plug).__name__
    for attr in ('name','description','icon','category'):
        if hasattr(plug, attr):
            info[attr] = str(getattr(plug, attr))[:100]
    info['has_bridge'] = hasattr(plug, 'bridge')
    if hasattr(plug, 'bridge'):
        try:
            info['bridge_methods'] = [m for m in dir(plug.bridge) if not m.startswith('_')][:50]
        except Exception as e:
            info['bridge_err'] = str(e)
result = info
"}
